contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint256 balBefore = address(c).balance;
        uint256 recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = address(c).balance;
        uint256 recordedAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            !reverted &&
            recordedBefore == 0 &&
            recordedAfter == 0 &&
            balAfter == balBefore
        );
    }

    receive() external payable {}
}

